package p;
import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import javax.persistence.*;
@Target({ ElementType.FIELD }) @Retention(RetentionPolicy.RUNTIME) @Documented @interface Cloneable {}
@Entity class PerfTest { @Id Long id; @Cloneable @Column(name = "test_name") String testName; }

package p;
import java.lang.annotation.*;
import javax.persistence.*;
/** a marker */ @java.lang.annotation.Retention(RetentionPolicy.RUNTIME) @interface Audited2 {}
@Entity class Doc { @Id Long id; @Audited2 String body; }

