import java.lang.annotation.*;
import javax.persistence.*;
import org.hibernate.annotations.AttributeBinderType;
@Retention(RetentionPolicy.RUNTIME) @AttributeBinderType(binder = TrackedBinder.class) @interface Tracked {}
@Entity class Doc { @Id Long id; @Tracked String body; }

