package p;
import org.springframework.context.annotation.Bean;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
public class DatabaseConfig {
    @Bean(name = "emf")
    public LocalContainerEntityManagerFactoryBean emf() {
        LocalContainerEntityManagerFactoryBean emf = new LocalContainerEntityManagerFactoryBean();
        emf.setPersistenceUnitName("ngrinder");
        return emf;
    }
}

package p;
import javax.sql.DataSource;
import org.springframework.boot.orm.jpa.EntityManagerFactoryBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
public class BoardJpaConfig {
    @Bean(name = "entityManagerFactory")
    LocalContainerEntityManagerFactoryBean entityManagerFactory(EntityManagerFactoryBuilder builder, DataSource dataSource) {
        return builder.dataSource(dataSource).packages("p.domain").persistenceUnit("default").build();
    }
}

package p;
import jakarta.persistence.EntityManagerFactory;
import jakarta.persistence.Persistence;
import org.springframework.context.annotation.Bean;
public class UnitConfig {
    @Bean
    public EntityManagerFactory entityManagerFactory() {
        return Persistence.createEntityManagerFactory("unit");
    }
}

package p;
import java.util.Properties;
import org.springframework.context.annotation.Bean;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
public class ShopConfig {
    @Bean
    public LocalContainerEntityManagerFactoryBean entityManagerFactory() {
        LocalContainerEntityManagerFactoryBean factory = new LocalContainerEntityManagerFactoryBean();
        factory.setJpaProperties(additionalProperties());
        return factory;
    }
    Properties additionalProperties() {
        Properties p = new Properties();
        p.setProperty("hibernate.physical_naming_strategy", "org.hibernate.boot.model.naming.CamelCaseToUnderscoresNamingStrategy");
        return p;
    }
}

package p;
import java.util.Map;
import org.hibernate.boot.model.naming.ImplicitNamingStrategyJpaCompliantImpl;
import org.hibernate.cfg.AvailableSettings;
import org.springframework.boot.autoconfigure.orm.jpa.HibernatePropertiesCustomizer;
import org.springframework.context.annotation.Bean;
public class NamingConfig {
    @Bean
    HibernatePropertiesCustomizer naming() {
        return (Map<String, Object> props) -> props.put(AvailableSettings.IMPLICIT_NAMING_STRATEGY, ImplicitNamingStrategyJpaCompliantImpl.class.getName());
    }
}

package p;
import org.springframework.boot.orm.jpa.EntityManagerFactoryBuilder;
import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;
public class SecondDataSource {
    EntityManagerFactoryBuilder builder(java.util.Map<String, ?> props) {
        return new EntityManagerFactoryBuilder(new HibernateJpaVendorAdapter(), props, null);
    }
}

package p;
import com.acme.orm.LocalContainerEntityManagerFactoryBean;
public class Holder {
    Object make() { return new LocalContainerEntityManagerFactoryBean(); }
}

package p;
import org.hibernate.boot.model.naming.PhysicalNamingStrategyStandardImpl;
import org.springframework.orm.hibernate5.LocalSessionFactoryBean;
public class SessionConfig {
    public LocalSessionFactoryBean sessionFactory() {
        LocalSessionFactoryBean factory = new LocalSessionFactoryBean();
        factory.setPhysicalNamingStrategy(new PhysicalNamingStrategyStandardImpl());
        return factory;
    }
}

package p;
import javax.sql.DataSource;
import org.springframework.orm.hibernate5.LocalSessionFactoryBuilder;
public class Legacy {
    Object build(DataSource ds) {
        LocalSessionFactoryBuilder b = new LocalSessionFactoryBuilder(ds);
        b.setImplicitNamingStrategy(null);
        return b.buildSessionFactory();
    }
}

package p;
import org.hibernate.boot.MetadataBuilder;
public class Boot {
    void configure(MetadataBuilder builder) {
        builder.applyImplicitNamingStrategy(null);
    }
}

package p;
class Settings { void setPhysicalNamingStrategy(Object s) {} }
class Use { void go(Settings s) { s.setPhysicalNamingStrategy(null); } }
